let commandIndex=0,commandConfirmed=[],choosingRow=false,pendingSpell=null;
function commandMembers(){return s.members.map((m,i)=>i).filter(i=>s.hp[i]>0&&!s.ailments[i].paralysis)}
function resetCommandEntry(){commandIndex=0;commandConfirmed=[];choosingRow=false;pendingSpell=null}
function confirmCommand(i){if(!s.enemy||logBusy())return;commandConfirmed[i]=true;commandIndex=commandMembers().indexOf(i)+1;choosingRow=false;pendingSpell=null;render()}
function commandSummary(i){let c=s.commands[i];if(c==='dispel')return '呪いを解く';if(c==='guard')return '守る';if(c==='spell')return magic(s.magicPlans[i]?.id)?.name||'呪文';if(c==='item')return weapon(s.itemPlans[i]?.id)?.name||'アイテム';let g=enemyGroups().find(g=>String(g.key)===String(s.attackRows[i]));return '戦う'+(g?' → '+(g.index+1)+'列':'')}
function renderCommandEntry(){let box=$('#commandentry'),members=commandMembers(),i=members[commandIndex],busy=logBusy(),ready=i===undefined;box.hidden=!visibleCombat();if(box.hidden)return;let disabled=busy?'disabled':'';box.innerHTML=busy?'<div>戦闘中</div>':ready?`<b class="commandheading">行動確認</b><div class="commandchoices"><button id="attack">この行動で戦う</button><button data-command-back>戻る</button></div>`:`<b class="commandheading">${NAMES[i]}：${pendingSpell?pendingSpell.name:choosingRow?'戦う':'行動'} <small>${commandIndex+1} / ${members.length}</small></b><div class="commandchoices">${pendingSpell?spellTargetButtons(pendingSpell):choosingRow?reachableEnemyGroups(i).map(g=>`<button data-row-choice="${g.key}">${g.index+1}列：${enemyDisplay(g.units[0])} ×${g.units.filter(e=>e.hp>0).length}</button>`).join(''):`${canWeaponAttack(i)?'<button data-command-choice="fight">戦う</button>':''}<button data-command-choice="guard">守る</button>${jobOf(i)===2?'<button data-command-choice="dispel">呪いを解く</button>':''}${hasSpells(i)?'<button data-command-choice="spell">呪文</button>':''}${medicineSlots(i).length?'<button data-command-choice="item">アイテム</button>':''}`}</div><button data-command-back ${commandIndex===0&&!choosingRow&&!pendingSpell?'disabled':''}>戻る</button>`;
 let popup=$('#commandreviewpopup');popup.hidden=!ready||busy||!s.enemy;popup.innerHTML=popup.hidden?'':`<b>行動確認</b><table class="commandreview" aria-label="選択した行動"><tbody>${members.map(j=>`<tr><th scope="row">${NAMES[j]}</th><td>${commandSummary(j)}</td></tr>`).join('')}</tbody></table>`;
 if(ready&&!busy){$('#attack').onclick=attack;$('#attack').hidden=false;$('#attack').disabled=false;}else if($('#attack'))$('#attack').hidden=true;$('#flee').hidden=busy||ready;
 box.onclick=e=>{if(logBusy()||!s.enemy)return;if(e.target.closest('[data-command-back]')){if(pendingSpell)pendingSpell=null;else if(choosingRow)choosingRow=false;else commandIndex=Math.max(0,commandIndex-1);render();return}let st=e.target.closest('[data-spell-target]');if(st&&pendingSpell){s.commands[i]='spell';s.magicPlans[i]={id:pendingSpell.id,target:+st.dataset.spellTarget};confirmCommand(i);return}let row=e.target.closest('[data-row-choice]');if(row){if(!reachableEnemyGroups(i).some(g=>String(g.key)===row.dataset.rowChoice))return;s.commands[i]='fight';s.attackRows[i]=row.dataset.rowChoice;confirmCommand(i);return}let b=e.target.closest('[data-command-choice]');if(!b)return;let c=b.dataset.commandChoice;if(c==='fight'){if(!canWeaponAttack(i))return;let groups=reachableEnemyGroups(i);if(groups.length===1){s.commands[i]='fight';s.attackRows[i]=groups[0].key;confirmCommand(i)}else{choosingRow=true;render()}}else if(c==='dispel'){s.commands[i]='dispel';confirmCommand(i)}else if(c==='guard'){s.commands[i]='guard';confirmCommand(i)}else if(c==='spell')openMagic(i);else openMedicine(i)};
}

function spellTargets(x){if(x.target==='ally')return s.hp.flatMap((h,i)=>h>0?[[i,`${NAMES[i]} ${h}/${maxHP(i)}`]]:[]);if(x.target==='enemy'||x.target==='group')return enemyGroups().filter(g=>g.units.some(e=>e.hp>0)).map(g=>[g.units.find(e=>e.hp>0).uid,`${g.index+1}列：${enemyDisplay(g.units[0])} ×${g.units.filter(e=>e.hp>0).length}`]);return []}
function spellTargetButtons(x){return spellTargets(x).map(([id,name])=>`<button data-spell-target="${id}">${name}</button>`).join('')}
function chooseBattleSpell(i,x){if(!s.enemy||logBusy()||spellReason(i,x))return;$('#magicdialog').close();let options=spellTargets(x);if(options.length>1){pendingSpell=x;choosingRow=false;render()}else{s.commands[i]='spell';s.magicPlans[i]={id:x.id,target:options.length?options[0][0]:null};confirmCommand(i)}}
